<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides field work order assignee behavior within the WorkIntel application. */ class FieldWorkOrderAssignee extends Model{protected $fillable=['field_work_order_id','member_id','role','accepted_at','completed_at'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['accepted_at'=>'datetime','completed_at'=>'datetime'];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}/** Handles the order operation for the current WorkIntel workflow. */ public function order():BelongsTo{return $this->belongsTo(FieldWorkOrder::class,'field_work_order_id');}}
